{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL injection vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4",
      "explanation": "The Apex class constructs a SOQL query by concatenating user input directly into the query string without using bind variables. This makes it vulnerable to SOQL injection attacks where malicious input could manipulate the query to access unauthorized data.",
      "remediation": "Replace the dynamic query construction with a static SOQL query using bind variables, e.g., 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50'."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOSL Injection in InvoiceSearchController",
      "severity": "High",
      "file": "InvoiceSearchController.cls",
      "lines": "4",
      "explanation": "The invoiceNum parameter is directly concatenated into a SOSL search term without any sanitization or binding. This allows an attacker to inject malicious SOSL syntax and potentially access unauthorized data. The @AuraEnabled method is callable by external users, making this a high-risk vulnerability.",
      "remediation": "Use a bind variable for the search term instead of concatenating it directly. Change the searchTerm assignment to: String searchTerm = 'Invoice-' + invoiceNum; and use Database.searchWithBinds() or ensure the input is validated against an allow-list before concatenation."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query Construction",
      "severity": "High",
      "file": "ReportFilterController.cls",
      "lines": "8-15",
      "explanation": "The controller constructs a SOQL query by directly concatenating user-provided filter values into the WHERE clause without any validation or escaping. This allows an attacker to inject malicious SOQL syntax, potentially leading to unauthorized data access or manipulation.",
      "remediation": "Use bind variables for all user inputs in SOQL queries. Validate field names against a predefined allow-list and escape values properly before concatenation."
    }
  ]
}

