{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4",
      "explanation": "The Apex class does not enforce CRUD/FLS checks. It directly queries and updates a Contact record without verifying if the user has sufficient permissions to read or modify the fields. This can lead to data exposure or modification beyond user permissions.",
      "remediation": "Add WITH USER_MODE to the SOQL query and use Security.stripInaccessible() on the returned records before processing them."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "High",
      "file": "AccountRatingService.cls",
      "lines": "Account acc = [SELECT Id, AnnualRevenue, Rating FROM Account WHERE Id = :accountId];",
      "explanation": "The code queries the Account object in system mode, which ignores field-level security. It reads AnnualRevenue even though the user may not have field permissions, and updates Rating without enforcing field-level security. This can lead to unauthorized data access or modification.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce field-level security, and use Security.stripInaccessible() before updating records to ensure only accessible fields are modified."
    },
    {
      "category": "C3",
      "title": "Sharing context violation",
      "severity": "High",
      "file": "AccountRatingService.cls",
      "lines": "public with sharing class AccountRatingService",
      "explanation": "Although the class is declared with sharing, it's @AuraEnabled and accessible to external users. The class runs in system mode when called externally, bypassing record-level sharing rules that should apply to the calling user.",
      "remediation": "Ensure that classes with @AuraEnabled methods enforce sharing by using WITH USER_MODE in queries or explicitly checking record access within the method."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation in Task creation",
      "severity": "High",
      "file": "CaseEscalationService.cls",
      "lines": "13-19",
      "explanation": "The code attempts to create a Task without checking if the user has create permissions on the Task object. The DmlException is silently caught, hiding potential FLS violations from the caller. Even though the permission set doesn't grant Task creation rights, the service still tries to insert a Task which could fail due to missing field-level security or object permissions.",
      "remediation": "Add a check for Task object create permissions using Security.isCreateable() before attempting to insert the Task, or use Security.stripInaccessible() to filter out inaccessible fields. Also remove the silent exception handling to properly report FLS violations."
    },
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "Medium",
      "file": "Case_Escalation_Agent.permissionset-meta.xml",
      "lines": "10-15",
      "explanation": "The permission set grants 'Edit' access to Case objects but does not grant 'Create' or 'Delete' access. However, the service class escalates cases by updating them and creating tasks, which requires both Case editing permissions and Task creation permissions. The permission set description states that task creation permission is intentionally not granted, but the code still attempts to create tasks.",
      "remediation": "Either grant the necessary Task object create permissions in the permission set or modify the service logic to avoid creating Tasks, ensuring that the permission set aligns with the actual functionality required."
    }
  ]
}

