  "findings": [
    {
      "category": "C3",
      "title": "Missing sharing enforcement",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "1",
      "explanation": "The class is declared 'without sharing', which means it ignores record-level sharing settings. This allows users to potentially access Case records they shouldn't be able to see based on their role or sharing rules.",
      "remediation": "Change the class declaration from 'without sharing' to 'with sharing' or 'inherited sharing' to enforce record-level sharing."
    },
    {
      "category": "C2",
      "title": "Missing CRUD/FLS enforcement",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "10",
      "explanation": "Although the code checks if Case is accessible, it doesn't enforce CRUD/FLS permissions on the individual records returned. The Security.stripInaccessible call is good but should be combined with WITH USER_MODE in SOQL to ensure proper permission checking.",
      "remediation": "Use WITH USER_MODE in the SOQL query or explicitly check CRUD/FLS permissions using Security.isCreateAllowed, Security.isUpdateAllowed etc., and ensure all data access respects user permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Missing sharing enforcement",
      "severity": "High",
      "file": "FinancialDashboardController.cls",
      "lines": "3",
      "explanation": "The class is declared 'without sharing', which means it ignores record-level sharing settings. This allows partner community users to access opportunities from all accounts, not just their own. Even though the query uses WITH USER_MODE, this only enforces object and field permissions, not record-level sharing.",
      "remediation": "Remove the 'without sharing' declaration and add 'with sharing' or 'inherited sharing' to the class declaration. This will ensure that record-level sharing rules are enforced for partner community users."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Class declared 'without sharing' allows bypass of record-level sharing",
      "severity": "High",
      "file": "DataAggregator.cls",
      "lines": "3",
      "explanation": "The DataAggregator class is declared 'without sharing', which means it ignores record-level sharing settings. Since it's exposed via @AuraEnabled, it can be called by authenticated users who may not have appropriate access to all records. The WITH USER_MODE in the query does not override the class-level sharing context.",
      "remediation": "Change the class declaration from 'without sharing' to 'with sharing' or 'inherited sharing'. If 'inherited sharing' is used, ensure that the entry point (e.g., @AuraEnabled method) is also properly declared with sharing."
    }
  ]
}

