    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "15, 16, 17, 18",
      "explanation": "The Support Agent Tools permission set grants ModifyAllData and ViewAllData permissions, which provide unrestricted access to all data in the org. These are powerful system permissions that should only be granted to administrators or integration users with a clear need. The permission set also includes AuthorApex and ApiEnabled, which further increase the risk.",
      "remediation": "Remove ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled from the permission set. Instead, grant only the specific object permissions needed for the user's role (e.g., Case object with read, edit, and view permissions) and ensure that the Apex class enforces proper security context using WITH USER_MODE or Security.stripInaccessible."
    }
  ]
}

